INSERT INTO dump_descriptions (base_key, description) VALUES ('enemyopt', 'Adds a saved enemy frame-rate setting that lowers enemy actor and component tick frequency to reduce update cost.') ON CONFLICT(base_key) DO UPDATE SET description=excluded.description, updated_at=CURRENT_TIMESTAMP;
INSERT INTO dump_descriptions (base_key, description) VALUES ('outlinedpheromones', 'Outlines active attackable targets near the local player and refreshes the marked set every 0.1 seconds.') ON CONFLICT(base_key) DO UPDATE SET description=excluded.description, updated_at=CURRENT_TIMESTAMP;
INSERT INTO dump_descriptions (base_key, description) VALUES ('fpm', 'Tracks frame-time spikes and periodically writes the time, frame count, and largest recorded dip in milliseconds to a local text file.') ON CONFLICT(base_key) DO UPDATE SET description=excluded.description, updated_at=CURRENT_TIMESTAMP;
